// คัดสมาชิกที่ "วันเปลี่ยนตู้ครั้งถัดไป" เหลือ ≤ 5 วัน (นับวันแบบเวลาไทย, รองรับข้ามเดือน)
const MS = 86400000;
const bkk = new Date(Date.now() + 7 * 3600 * 1000);   // Asia/Bangkok = UTC+7 ไม่มี DST
const todayUTC = Date.UTC(bkk.getUTCFullYear(), bkk.getUTCMonth(), bkk.getUTCDate());

const out = [];
for (const item of $input.all()) {
  const line_uid = item.json.line_uid;
  const day = Number(item.json.day);                   // 1–28 (บังคับที่ DB) → Date.UTC ปลอดภัยทุกเดือน
  if (!line_uid || !day) continue;
  let y = bkk.getUTCFullYear(), m = bkk.getUTCMonth();
  let closet = Date.UTC(y, m, day);
  if (closet < todayUTC) closet = Date.UTC(y, m + 1, day);   // เดือนนี้ผ่านไปแล้ว → เดือนหน้า
  const daysLeft = Math.round((closet - todayUTC) / MS);
  if (daysLeft > 5) continue;
  const d = new Date(closet);
  const month = d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0'); // 'YYYY-MM' ของกล่อง
  out.push({ json: { line_uid, day, month, days_left: daysLeft, closet_date: d.toISOString().slice(0, 10) } });
}
return out;

function bubble(title, body, btnLabel, uri, extra) {
  const bodyContents = [
    { type: 'text', text: title, weight: 'bold', size: 'md', wrap: true, color: '#1F2A22' },
    { type: 'text', text: body, size: 'sm', color: '#6B7A6E', wrap: true }
  ];
  if (extra) bodyContents.push({ type: 'text', text: extra, size: 'xs', color: '#8A9388', wrap: true, margin: 'md' });
  return {
    type: 'bubble',
    header: { type: 'box', layout: 'vertical', backgroundColor: '#3E5C46', paddingAll: '16px',
      contents: [ { type: 'text', text: 'LLOOP', color: '#FFFFFF', weight: 'bold', size: 'sm' } ] },
    body: { type: 'box', layout: 'vertical', spacing: 'sm', paddingAll: '20px', contents: bodyContents },
    footer: { type: 'box', layout: 'vertical', paddingAll: '16px',
      contents: [ { type: 'button', style: 'primary', color: '#3E5C46', height: 'sm',
        action: { type: 'uri', label: btnLabel, uri: uri } } ] }
  };
}

// ส่ง LINE เฉพาะคนที่ "เพิ่งถูกล็อกกล่องรอบนี้จริง ๆ"
// (PATCH ตั้ง Prefer: return=representation → ได้แถวที่อัปเดตกลับมา; [] = กล่องไม่ใช่ draft แล้ว
//  เช่น confirm ไปแล้วเมื่อวาน / ลูกค้ากด skip → ไม่ส่งซ้ำ)
const byUid = {};
for (const m of $('คัดสมาชิกที่เหลือ ≤ 5 วัน').all()) byUid[m.json.line_uid] = m.json;

const out = [];
for (const item of $input.all()) {
  const rows = item.json.body;                          // fullResponse → body = แถวที่ PATCH โดน
  if (!Array.isArray(rows) || rows.length === 0) continue;
  const uid = rows[0].line_uid;
  const member = byUid[uid] || {};
  const dayText = member.day ? String(member.day) : '';
  const title = 'กล่องของคุณล็อกแล้วค่ะ';
  const bodyText = 'เจอกันวันที่ ' + dayText + ' นะคะ 💚 ถ้าอยากปรับอะไรเพิ่ม ทัก LINE ทีมงานได้เลยค่ะ';
  const contents = bubble(title, bodyText, 'ดูกล่องของฉัน',
                          'https://wearlloop-dotcom.github.io/closet-day.html');
  out.push({ json: { lineBody: { to: uid, messages: [{ type: 'flex',
    altText: 'กล่องของคุณล็อกแล้ว เจอกันวันที่ ' + dayText + ' นะคะ 💚', contents }] } } });
}
return out;
